INSERT INTO _migration_461_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_wst_b002_009', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The greatest long-term environmental danger at informal e-waste burning sites such as Agbogbloshie is that', 'multiple_choice', NULL, '["A. the smoke produces an unpleasant smell over the city","B. the noise from the site disturbs nearby residents","C. heavy metals such as lead and mercury leach into soil and groundwater and enter food chains","D. the land becomes unavailable for growing vegetables"]', 'C', 'Burning cables and circuit boards releases lead, mercury and cadmium; these metals persist for decades, leach into soil and groundwater, and bioaccumulate in crops, fish and people, causing neurological and kidney damage long after burning stops. Smell, noise and land loss are real but short-term local nuisances by comparison. Therefore the correct answer is C: heavy metals such as lead and mercury leach into soil and groundwater and enter food chains.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Evaluate', 'AO3', NULL, NULL, NULL),
('q_wisc_wst_b002_010', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Methane produced by decomposing refuse in landfills is a concern mainly because it', 'multiple_choice', NULL, '["A. gives refuse its characteristic sweet smell","B. reacts with rainwater to form acid rain directly","C. attracts mosquitoes that spread malaria","D. is a potent greenhouse gas and can form explosive mixtures in enclosed spaces"]', 'D', 'Anaerobic decomposition of organic waste releases methane, which traps far more heat per molecule than carbon dioxide and can accumulate to explosive concentrations in buildings or pipes near landfills; modern sites therefore vent or capture it. It is odourless, does not form acid rain directly and does not attract mosquitoes. Therefore the correct answer is D: is a potent greenhouse gas and can form explosive mixtures in enclosed spaces.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, NULL),
('q_wisc_wst_b002_011', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A community of 400 households generates an average of 2.5 kg of refuse per household per day. Calculate the mass of refuse generated in the community per week, and the number of trips a 5-tonne truck must make per week to remove it. (1 tonne = 1 000 kg)', 'calculation', NULL, NULL, '7 000 kg per week; 2 trips', 'Daily refuse = 400 x 2.5 kg = 1 000 kg. Weekly refuse = 1 000 kg x 7 = 7 000 kg = 7 tonnes. Number of trips = 7 / 5 = 1.4, so the truck must make 2 trips per week (a fraction of a trip still requires a full journey).', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_wst_b002_012', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A school collects 250 kg of waste every week. If 60% of the waste is organic material suitable for composting, calculate the mass of organic waste available for the school compost heap each week.', 'calculation', NULL, NULL, '150 kg', 'Organic fraction = 60% of 250 kg = (60 / 100) x 250 = 0.6 x 250 = 150 kg. So 150 kg of organic waste goes to the compost heap weekly, leaving 100 kg of non-organic waste for recycling or disposal.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_wst_b002_013', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A household in Accra produces mixed refuse every day. Describe how the household can manage its waste safely from generation to final disposal.', 'structured', NULL, NULL, '(a) Separate biodegradable waste such as food scraps from non-biodegradable waste such as plastics, glass and metals into different covered bins; keep hazardous items such as used batteries and broken bulbs apart for special collection. (b) Compost it: place the organic waste in a pit or bin, keep it moist and turn it regularly so that micro-organisms decompose it aerobically into compost manure that can be used on a garden or farm. (c) Refuse blocks the gutters so rainwater cannot flow, causing flooding; the dump also breeds mosquitoes, flies and rats and can contaminate water, spreading diseases such as malaria and cholera.', '(a) Separate biodegradable waste such as food scraps from non-biodegradable waste such as plastics, glass and metals into different covered bins; keep hazardous items such as used batteries and broken bulbs apart for special collection. (b) Compost it: place the organic waste in a pit or bin, keep it moist and turn it regularly so that micro-organisms decompose it aerobically into compost manure that can be used on a garden or farm. (c) Refuse blocks the gutters so rainwater cannot flow, causing flooding; the dump also breeds mosquitoes, flies and rats and can contaminate water, spreading diseases such as malaria and cholera.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL);
INSERT INTO _migration_461_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_wisc_wst_b002_013_a', 'q_wisc_wst_b002_013', 'a', 'State two ways the household should separate its waste at source.', '2', 'Separate biodegradable waste such as food scraps from non-biodegradable waste such as plastics, glass and metals into different covered bins; keep hazardous items such as used batteries and broken bulbs apart for special collection.', '1'),
('sqp_q_wisc_wst_b002_013_b', 'q_wisc_wst_b002_013', 'b', 'Describe one beneficial way of disposing of the organic fraction of the waste.', '2', 'Compost it: place the organic waste in a pit or bin, keep it moist and turn it regularly so that micro-organisms decompose it aerobically into compost manure that can be used on a garden or farm.', '2'),
('sqp_q_wisc_wst_b002_013_c', 'q_wisc_wst_b002_013', 'c', 'State two dangers of dumping refuse into gutters instead of using a waste container.', '2', 'Refuse blocks the gutters so rainwater cannot flow, causing flooding; the dump also breeds mosquitoes, flies and rats and can contaminate water, spreading diseases such as malaria and cholera.', '3');
INSERT INTO _migration_461_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_461_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_461_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_461_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_461_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_461_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_461_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_461_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_461_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 5 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_461_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 5 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_461_expected e ON e.id = q.id) = 5 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_461_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
